import { createHash } from 'crypto';
import envPaths from 'env-paths';
import { readFile, writeFile, mkdir } from 'fs/promises';
import { join } from 'path';

const SYSTEM_PROMPT_VERSION = 'v2'; // bump this if the prompt itself changes
const cacheDir = envPaths('invtrack').cache;

function cacheKey(invoice) {
  const material = JSON.stringify({ invoice, promptVersion: SYSTEM_PROMPT_VERSION });
  return createHash('sha256').update(material).digest('hex');
}

async function explainInvoice(invoice, options) {
  const key = cacheKey(invoice);
  const cachePath = join(cacheDir, `explain-${key}.json`);
  if (!options.refresh) {
    try {
      const cached = JSON.parse(await readFile(cachePath, 'utf-8'));
      return cached.text;
    } catch { /* cache miss, fall through */ }
  }
  const text = await callClaude(invoice);
  await mkdir(cacheDir, { recursive: true });
  await writeFile(cachePath, JSON.stringify({ text }), 'utf-8');
  return text;
}
```

The cache directory itself is the same OS-conventional location from the config module's env-paths setup — a cache is disposable by definition, which is exactly what makes it safe to store this way rather than treating it like real config or data.

